CREATE TABLE IF NOT EXISTS reports (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, reporter_id BIGINT UNSIGNED NOT NULL, target_type VARCHAR(40) NOT NULL, target_id BIGINT UNSIGNED NOT NULL, reason VARCHAR(80) NOT NULL, description TEXT NULL, status ENUM('open','reviewing','resolved','dismissed') NOT NULL DEFAULT 'open', resolution TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(id), INDEX idx_reports_status(status));
CREATE TABLE IF NOT EXISTS platform_commissions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, contract_id BIGINT UNSIGNED NOT NULL, employer_id BIGINT UNSIGNED NOT NULL, freelancer_id BIGINT UNSIGNED NOT NULL, gross_amount DECIMAL(12,2) NOT NULL, rate DECIMAL(5,2) NOT NULL, commission_amount DECIMAL(12,2) NOT NULL, currency VARCHAR(3) NOT NULL DEFAULT 'USD', status ENUM('pending','collected','refunded') NOT NULL DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uq_commission_contract(contract_id));
CREATE TABLE IF NOT EXISTS platform_settings (setting_key VARCHAR(80) NOT NULL PRIMARY KEY, setting_value VARCHAR(255) NOT NULL);
INSERT INTO platform_settings(setting_key,setting_value) VALUES ('commission_rate','10.00') ON DUPLICATE KEY UPDATE setting_key=setting_key;